import { useCallback, useEffect, useRef, useState } from 'react';
import { adminApi, mediaUrl } from '../api/client';
import { usePanelI18n } from '../i18n';
import { LoadingState, ErrorState, EmptyState } from './States';
import Modal from './Modal';
import ConfirmDialog from './ConfirmDialog';
import TranscodingBadge from './TranscodingBadge';
import MediaSpec from './MediaSpec';
import { needsDownscaleWarning, probeVideoSize } from '../utils/videoProbe';

/**
 * Media kutubxonadan fayl tanlash yoki yangisini yuklash.
 *
 * Ikki vazifani birlashtiradi (§54 dagi creator naqshi kabi): avval mavjudini
 * qidiradi, topilmasa shu yerning o'zida yuklaydi.
 *
 * `spec` - qaysi maydon uchun ochilgani (`mediaSpecs.js` kaliti). Berilsa,
 * yuklash tugmasi TAGIDA tavsiya etilgan o'lcham turadi.
 *
 * ⚠️ Nega bu yerda ham kerak. Kutubxona oynasi maydonni to'sib qo'yadi,
 * ya'ni maydon yonidagi yozuv aynan fayl tanlanadigan onda ko'rinmay
 * qoladi. Bo'sh berilsa (masalan «Media» bo'limidan ochilganda) hech narsa
 * chizilmaydi: u yerda fayl qaysi maydonga borishi hali ma'lum emas.
 */
export default function MediaPicker({ open, onClose, onSelect, spec, type = 'IMAGE' }) {
  const { t } = usePanelI18n();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selected, setSelected] = useState(null);
  const [progress, setProgress] = useState(null);
  const fileRef = useRef(null);

  /**
   * Yuklash uchun tasdiq kutayotgan 4K fayl.
   *
   * ⚠️ Fayl SAQLANADI, `<input>` esa tozalanadi. Admin «baribir
   * yuklash» desa, faylni qaytadan tanlashi kerak bo'lardi — va bu
   * ogohlantirishni foydali emas, xalaqit beruvchi qilardi.
   */
  const [oversized, setOversized] = useState(null);

  const load = useCallback(() => {
    setLoading(true);
    setError(null);
    adminApi
      .media({ page: 0, size: 60, type })
      .then((res) => setItems(res.items || []))
      .catch(setError)
      .finally(() => setLoading(false));
  }, [type]);

  useEffect(() => {
    if (open) {
      setSelected(null);
      load();
    }
  }, [open, load]);

  /**
   * Fayl tanlandi.
   *
   * ⚠️ VIDEO uchun avval o'lcham o'qiladi — yuklash BOSHLANMASDAN
   * oldin. 4 GB yuklab bo'lgach «bu 4K ekan» deyish kech bo'lardi.
   */
  async function handleUpload(event) {
    const file = event.target.files?.[0];
    if (fileRef.current) fileRef.current.value = '';
    if (!file) return;

    if (type === 'VIDEO') {
      const size = await probeVideoSize(file);
      if (needsDownscaleWarning(size)) {
        setOversized({ file, size });
        return;
      }
    }

    await upload(file);
  }

  async function upload(file) {
    setProgress(0);
    setError(null);
    try {
      const created = await adminApi.uploadMedia(file, 'content', setProgress);
      setItems((prev) => [created, ...prev]);
      setSelected(created.id);
    } catch (err) {
      setError(err);
    } finally {
      setProgress(null);
    }
  }

  return (
    <Modal
      open={open}
      title={t('media.pick')}
      onClose={onClose}
      width={760}
      footer={
        <>
          <button type="button" className="uz-btn uz-btn-ghost" onClick={onClose}>
            {t('common.cancel')}
          </button>
          <button
            type="button"
            className="uz-btn uz-btn-primary"
            disabled={!selected}
            onClick={() => {
              onSelect(selected);
              onClose();
            }}
          >
            {t('common.select')}
          </button>
        </>
      }
    >
      <div className="mb-4">
        <input
          ref={fileRef}
          type="file"
          /* ⚠️ `video/*` EMAS — ro'yxat server bilan AYNAN bir xil
             (`LocalStorageService.ALLOWED`). `video/*` bo'lsa brauzer
             `.flv` yoki `.wmv` ni ham taklif qilardi va admin faylni
             tanlagach 422 xato olardi, nima uchun ekanini tushunmasdan. */
          accept={type === 'VIDEO'
            ? '.mp4,.mov,.webm,.m4v,.mkv,.avi'
              + ',video/mp4,video/quicktime,video/webm,video/x-matroska,video/x-msvideo'
            : '.jpg,.jpeg,.png,.webp,.gif,.svg,image/*'}
          onChange={handleUpload}
          style={{ display: 'none' }}
          id="uz-media-upload"
        />
        <label htmlFor="uz-media-upload" className="uz-btn uz-btn-ghost" style={{ cursor: 'pointer' }}>
          ⬆ {t('media.upload')}
        </label>
        {spec && <MediaSpec name={spec} />}
        {progress !== null && (
          <div className="uz-progress mt-3" role="progressbar" aria-valuenow={progress}>
            <div style={{ width: `${progress}%` }} />
          </div>
        )}
      </div>

      {/*
        ⚠️ Xavfli amal EMAS, shuning uchun tugma qizil emas: bu
        tezlik haqidagi maslahat, xato haqidagi ogohlantirish emas.
        Qizil tugma adminni «nimadir buzildi» deb o'ylatardi.
      */}
      <ConfirmDialog
        open={Boolean(oversized)}
        danger={false}
        title={t('media.bigVideo.title')}
        message={oversized
          ? t('media.bigVideo.message')
              .replace('{w}', oversized.size.width)
              .replace('{h}', oversized.size.height)
          : ''}
        note={t('media.bigVideo.note')}
        confirmLabel={t('media.bigVideo.confirm')}
        onConfirm={() => {
          const pending = oversized.file;
          setOversized(null);
          upload(pending);
        }}
        onCancel={() => setOversized(null)}
      />

      {loading ? (
        <LoadingState rows={3} />
      ) : error ? (
        <ErrorState error={error} onRetry={load} />
      ) : items.length === 0 ? (
        <EmptyState icon="🖼" />
      ) : (
        <div className="uz-media-grid">
          {items.map((m) => (
            <button
              key={m.id}
              type="button"
              className={`uz-media-tile ${selected === m.id ? 'selected' : ''}`}
              onClick={() => setSelected(m.id)}
              aria-pressed={selected === m.id}
              title={m.originalFilename || String(m.id)}
            >
              {m.type === 'IMAGE' ? (
                <img src={mediaUrl(m.id)} alt="" loading="lazy" />
              ) : (
                <span style={{ fontSize: 28 }} aria-hidden="true">🎞</span>
              )}
              {/* ⚠️ `=== false` ataylab: rasm va hujjatda `playable`
                  `null` bo'ladi — «o'ynatib bo'lmaydi» emas, «bu savol
                  tegishli emas». `!m.playable` bo'lsa har bir rasmga
                  ogohlantirish yopishtirilardi. */}
              {m.playable === false && (
                <span className="uz-media-warn" title={t('media.notPlayableHint')}>
                  ⚠ {t('media.notPlayable')}
                </span>
              )}
              {/* ⚠️ Yangi yuklangan video darhol «Navbatda» bo'lib
                  ko'rinadi. Usiz admin yuklash tugagach uni TAYYOR deb
                  o'ylardi, aslida qayta ishlash endi boshlanadi. */}
              {m.transcoding && m.transcoding.status !== 'READY' && (
                <span className="uz-media-tc">
                  <TranscodingBadge transcoding={m.transcoding} compact />
                </span>
              )}
            </button>
          ))}
        </div>
      )}
    </Modal>
  );
}
